B.dnm=new A.cM("create_tutoring_student_dialog","Novo / Editar Aluno","Tutoria",'Di\xe1logo de cria\xe7\xe3o/edi\xe7\xe3o de um aluno no diret\xf3rio standalone de tutoria (tutoring_students) \u2014 n\xe3o \xe9 a mesma tabela que as entidades financeiras (public.entities). Aberto diretamente ou a partir do di\xe1logo "Adicionar aluno" de uma turma.',B.p,B.b2M,B.p,B.ld,B.hGi,null,"lib/features/tutoring/presentation/widgets/create_tutoring_student_dialog.dart.")
