B.dmP=new A.cM("tutoring_add_roster_student_dialog","Adicionar Aluno \xe0 Turma","Tutoria",'Escolhe um aluno j\xe1 existente no diret\xf3rio (ou cria um novo, sem sair do di\xe1logo) e junta-o ao plantel da turma. Alunos j\xe1 no plantel n\xe3o aparecem na lista. Remover um aluno da turma noutro ponto do ecr\xe3 (separador Alunos) n\xe3o apaga a linha \u2014 apenas marca "active = false", preservando o hist\xf3rico de sess\xf5es/avalia\xe7\xf5es/cobran\xe7as desse aluno nesta turma.',B.hkh,B.ahc,B.p,B.hvP,B.p,null,"lib/features/tutoring/presentation/widgets/roster_tab.dart.")
