B.ewj=new A.hF("Sangue","N\xfamero de gl\xf3bulos vermelhos, as c\xe9lulas que levam o oxig\xe9nio. Faz parte do hemograma, a contagem das c\xe9lulas do sangue.","Desidrata\xe7\xe3o, tabaco, apneia do sono ou doen\xe7as da medula.","Normalmente acompanha a anemia (ver hemoglobina).",u.s,null)
B.ewS=new A.hF("Sangue","Percentagem do sangue ocupada pelos gl\xf3bulos vermelhos.","Desidrata\xe7\xe3o, tabaco, apneia do sono; sangue mais espesso.","Anemia ou excesso de l\xedquidos.","Beber \xe1gua suficiente; tratar a causa identificada pelo m\xe9dico.",null)
B.ewe=new A.hF("Sangue","Tamanho m\xe9dio dos gl\xf3bulos vermelhos. Ajuda a perceber o tipo de anemia.","Gl\xf3bulos grandes: falta de vitamina B12 ou \xe1cido f\xf3lico, \xe1lcool, problemas da tiroide ou do f\xedgado.","Gl\xf3bulos pequenos: t\xedpico de falta de ferro ou de tra\xe7o talass\xe9mico.","S\xf3 tem import\xe2ncia junto com a hemoglobina; o m\xe9dico interpreta o conjunto.",null)
B.ew3=new A.hF("Sangue","Quantidade m\xe9dia de hemoglobina dentro de cada gl\xf3bulo vermelho.","Acompanha gl\xf3bulos grandes (B12/\xe1cido f\xf3lico).","T\xedpico de falta de ferro.","Interpreta-se junto com a hemoglobina e o VGM.",null)
B.ewP=new A.hF("Sangue","Concentra\xe7\xe3o de hemoglobina dentro dos gl\xf3bulos vermelhos.","Raro; algumas doen\xe7as dos gl\xf3bulos vermelhos.","Falta de ferro.","Interpreta-se junto com a hemoglobina.",null)
B.ewm=new A.hF("Sangue","Mede se os gl\xf3bulos vermelhos t\xeam todos o mesmo tamanho (alto = tamanhos muito diferentes).","In\xedcio de falta de ferro, B12 ou \xe1cido f\xf3lico, ou mistura de causas de anemia.",null,"S\xf3 tem valor junto com o resto do hemograma.",null)
B.ew1=new A.hF("Defesas","Gl\xf3bulos brancos: as c\xe9lulas de defesa contra infe\xe7\xf5es.","Sobe com infe\xe7\xf5es, inflama\xe7\xe3o, stress, tabaco e alguns medicamentos (ex.: cortisona). Valores muito altos e persistentes s\xe3o investigados.","Pode baixar com v\xedrus, alguns medicamentos ou doen\xe7as da medula. Ligeiramente baixo e est\xe1vel costuma n\xe3o ter import\xe2ncia.","Repetir se estiver alterado sem raz\xe3o (ex.: depois de uma gripe).",null)
B.ewl=new A.hF("Defesas","Gl\xf3bulos brancos que combatem sobretudo bact\xe9rias.","Infe\xe7\xf5es bacterianas, inflama\xe7\xe3o, stress, tabaco, cortisona.","V\xedrus, alguns medicamentos; muito baixos aumentam o risco de infe\xe7\xf5es.","Interpreta-se com o total de leuc\xf3citos.",null)
B.ewR=new A.hF("Defesas","Gl\xf3bulos brancos ligados a alergias e parasitas.","Alergias, asma, rinite, eczema, parasitas, alguns medicamentos.","Normalmente sem import\xe2ncia.","Controlar as alergias.",null)
B.ewL=new A.hF("Defesas","Gl\xf3bulos brancos raros, ligados a rea\xe7\xf5es al\xe9rgicas.","Alergias, inflama\xe7\xe3o cr\xf3nica; raramente doen\xe7as da medula.",null,"Isoladamente tem pouca import\xe2ncia.",null)
B.ewI=new A.hF("Defesas",'Gl\xf3bulos brancos que combatem v\xedrus e fazem a "mem\xf3ria" imunit\xe1ria.',"Infe\xe7\xf5es por v\xedrus (gripe, mononucleose); se persistirem muito altos, investiga-se.","Stress, cortisona, algumas infe\xe7\xf5es.","Repetir ap\xf3s recuperar de uma infe\xe7\xe3o.",null)
B.ewt=new A.hF("Defesas",'Gl\xf3bulos brancos que "limpam" restos de infe\xe7\xf5es e inflama\xe7\xe3o.',"Recupera\xe7\xe3o de infe\xe7\xf5es, inflama\xe7\xe3o cr\xf3nica.","Normalmente sem import\xe2ncia.","Interpreta-se com o resto do hemograma.",null)
B.ewV=new A.hF("Sangue","Pequenas c\xe9lulas que fazem o sangue coagular e param as hemorragias.","Inflama\xe7\xe3o, falta de ferro, depois de cirurgias; muito altas aumentam o risco de tromboses.","N\xf3doas negras f\xe1ceis, sangramento das gengivas ou do nariz. Causas: v\xedrus, medicamentos, f\xedgado, \xe1lcool.","Evitar \xe1lcool; o m\xe9dico investiga se persistirem alteradas.","Com f\xedgado gordo as plaquetas podem baixar com os anos \u2014 \xe9 um dos valores que vigia o f\xedgado. As suas est\xe3o normais.")
B.ew8=new A.hF("Sangue","Tamanho m\xe9dio das plaquetas.","Plaquetas jovens (a medula est\xe1 a produzir mais).","Pouca import\xe2ncia isoladamente.","Interpreta-se com o n\xfamero de plaquetas.",null)
B.ewW=new A.hF("A\xe7\xfacar","Hemoglobina glicada: mostra a M\xc9DIA do a\xe7\xfacar no sangue dos \xfaltimos 2\u20133 meses. Abaixo de 5,7% \xe9 normal; 5,7\u20136,4% \xe9 pr\xe9-diabetes; 6,5% ou mais \xe9 diabetes.","O a\xe7\xfacar em excesso vai estragando lentamente os vasos pequenos (olhos \u2192 perda de vis\xe3o; rins \u2192 insufici\xeancia renal; nervos dos p\xe9s \u2192 formigueiros, feridas que n\xe3o saram) e os grandes (enfarte, AVC, m\xe1 circula\xe7\xe3o nas pernas). Tamb\xe9m aumenta infe\xe7\xf5es e piora a disfun\xe7\xe3o er\xe9til.",null,"Perder peso (5\u201310% j\xe1 melhora muito); cortar a\xe7\xfacar, sumos, bolos e p\xe3o branco; preferir hidratos integrais e em pouca quantidade; caminhar depois das refei\xe7\xf5es; dormir bem com o CPAP.","Com tens\xe3o alta, excesso de peso, apneia do sono e f\xedgado gordo, o a\xe7\xfacar merece vigil\xe2ncia pr\xf3xima. Veja a evolu\xe7\xe3o mais abaixo e combine com o m\xe9dico a frequ\xeancia das an\xe1lises e os exames de olhos, rins e p\xe9s.")
B.ew7=new A.hF("A\xe7\xfacar",'\xc9 a HbA1c "traduzida" para mg/dL, a unidade do medidor de glicemia de casa: a m\xe9dia do a\xe7\xfacar nos \xfaltimos 2 a 3 meses. Calcula-se por f\xf3rmula (28,7 \xd7 HbA1c \u2212 46,7), n\xe3o \xe9 uma medi\xe7\xe3o nova.',"Acima de cerca de 140 mg/dL corresponde a uma HbA1c de 6,5% ou mais (faixa de diabetes). O a\xe7\xfacar alto durante meses vai danificando os vasos pequenos (olhos, rins, nervos dos p\xe9s) e os grandes (cora\xe7\xe3o, c\xe9rebro, pernas).",null,"O mesmo que para a HbA1c: perder peso, menos a\xe7\xfacar, sumos e farinhas brancas, hidratos integrais e em pouca quantidade, caminhar depois das refei\xe7\xf5es, dormir bem com o CPAP e tomar a medica\xe7\xe3o que o m\xe9dico indicar.",null)
B.ewk=new A.hF("A\xe7\xfacar",'A\xe7\xfacar no sangue de manh\xe3, em jejum de 8\u201312 h. Normal abaixo de 100 mg/dL; 100\u2013125 \xe9 "anomalia da glicemia em jejum" (pr\xe9-diabetes); 126 ou mais (confirmado) \xe9 diabetes.',"Ver HbA1c: o a\xe7\xfacar alto continuado danifica vasos, rins, olhos e nervos. Muito alto (acima de 250\u2013300) d\xe1 sede, urinar muito, cansa\xe7o e pode ser urgente.","Abaixo de 70: tremores, suores, fome, confus\xe3o. Coma algo com a\xe7\xfacar e avise o m\xe9dico se repetir.","Igual \xe0 HbA1c: peso, menos a\xe7\xfacar e farinhas brancas, caminhar, dormir bem.","O laborat\xf3rio pode usar um limite de 110, mas pelos crit\xe9rios atuais de 100 a 125 j\xe1 \xe9 pr\xe9-diabetes e 126 ou mais, confirmado, \xe9 diabetes. Compare com a HbA1c, que \xe9 mais est\xe1vel.")
B.ewA=new A.hF("A\xe7\xfacar","Hormona que mete o a\xe7\xfacar dentro das c\xe9lulas.","Resist\xeancia \xe0 insulina: o corpo precisa de cada vez mais insulina \u2014 t\xedpico do excesso de peso abdominal e caminho para a diabetes.",null,"Perder peso abdominal e fazer exerc\xedcio reduzem a resist\xeancia.",null)
B.ewi=new A.hF("Rins","Res\xedduo das prote\xednas que os rins eliminam na urina.","Desidrata\xe7\xe3o, muita prote\xedna, diur\xe9ticos, ou rins a filtrar menos.","Pouca prote\xedna na dieta; sem import\xe2ncia na maioria dos casos.","Beber \xe1gua suficiente.",null)
B.ew4=new A.hF("Rins","\xc9 a ureia expressa de outra forma; l\xea-se como a ureia.","Desidrata\xe7\xe3o ou rins a filtrar menos.","Sem import\xe2ncia na maioria dos casos.","Beber \xe1gua suficiente.",null)
B.ewo=new A.hF("Rins","Res\xedduo dos m\xfasculos que s\xf3 os rins eliminam. Quanto mais alta, pior os rins est\xe3o a filtrar.","Rins a filtrar menos (doen\xe7a renal, desidrata\xe7\xe3o, alguns medicamentos como anti-inflamat\xf3rios). A doen\xe7a renal n\xe3o d\xe1 sintomas at\xe9 estar avan\xe7ada \u2014 por isso se vigia.","Pouca massa muscular; sem import\xe2ncia.","Controlar a tens\xe3o e o a\xe7\xfacar (s\xe3o as principais causas de doen\xe7a renal); beber \xe1gua; evitar anti-inflamat\xf3rios (ibuprofeno, diclofenac).","Toma olmesartan e hidroclorotiazida, que mexem com os rins \u2014 \xe9 bom vigiar 1\u20132 vezes por ano. Os seus valores est\xe3o \xf3timos.")
B.ewf=new A.hF("Rins","Taxa de filtra\xe7\xe3o: quantos mL de sangue os rins limpam por minuto (calculada a partir da creatinina). Acima de 90 \xe9 normal; abaixo de 60 durante 3 meses \xe9 doen\xe7a renal cr\xf3nica.",null,"Rins a perder capacidade: acumulam-se res\xedduos, sobe a tens\xe3o, h\xe1 anemia e problemas \xf3sseos nas fases avan\xe7adas.","Tens\xe3o e a\xe7\xfacar controlados; evitar anti-inflamat\xf3rios; n\xe3o abusar de suplementos.","96 em 2025: rins normais.")
B.ewJ=new A.hF("Rins","Res\xedduo de subst\xe2ncias (purinas) da carne, marisco, \xe1lcool e das pr\xf3prias c\xe9lulas; \xe9 eliminado pelos rins.","Pode cristalizar nas articula\xe7\xf5es (gota: dedo grande do p\xe9 muito inchado, vermelho e doloroso) e nos rins (pedras). Associa-se a tens\xe3o alta, obesidade e doen\xe7a renal.","Raramente tem import\xe2ncia.","Beber 1,5\u20132 L de \xe1gua; menos carnes vermelhas, v\xedsceras, marisco, enchidos, cerveja e bebidas a\xe7ucaradas; perder peso gradualmente (dietas muito r\xe1pidas sobem-no temporariamente).","Est\xe1 sempre no limite (6,9 \u2192 7,2 \u2192 7,1). A hidroclorotiazida, presente no comprimido da tens\xe3o, faz subir o \xe1cido \xfarico \u2014 fale disto com o m\xe9dico.")
B.ex0=new A.hF("Rins","Serve apenas para calcular a rela\xe7\xe3o albumina/creatinina; sozinha n\xe3o se interpreta.",null,null,"Sem a\xe7\xe3o necess\xe1ria.",null)
B.ew2=new A.hF("Rins","Prote\xedna que normalmente n\xe3o passa para a urina; usa-se na rela\xe7\xe3o albumina/creatinina.","Sinal precoce de dano nos rins e nos vasos, t\xedpico da diabetes e da tens\xe3o alta.",null,"Ver rela\xe7\xe3o albumina/creatinina.",null)
B.ewX=new A.hF("Rins",'Mede se os rins est\xe3o a "deixar escapar" prote\xedna para a urina. Abaixo de 30 mg/g \xe9 normal.',"\xc9 o primeiro sinal de que a tens\xe3o alta ou o a\xe7\xfacar est\xe3o a danificar os rins (e os vasos em geral), anos antes de a creatinina subir. Aumenta o risco cardiovascular.",null,"Controlar tens\xe3o e a\xe7\xfacar; o olmesartan que toma tamb\xe9m protege os rins.","9,9 em 2024: normal \u2014 boa not\xedcia com tens\xe3o alta e pr\xe9-diabetes. Conv\xe9m repetir uma vez por ano.")
B.ewU=new A.hF("Gorduras","Soma de todo o colesterol (bom e mau). Sozinho diz pouco: o que conta \xe9 o LDL e o HDL.","Mais colesterol a circular, mais risco de placas nas art\xe9rias (enfarte, AVC).",null,"Ver LDL.",null)
B.ewy=new A.hF("Gorduras",'O colesterol "mau". Em excesso entra nas paredes das art\xe9rias e forma placas que as estreitam e podem romper e entupir de repente.',"Quanto mais alto e durante mais anos, maior o risco de enfarte, AVC e m\xe1 circula\xe7\xe3o nas pernas. N\xe3o d\xe1 sintomas at\xe9 ao acidente. O alvo depende do risco: moderado <100, alto <70, muito alto <55.",null,"Tomar a estatina todos os dias; menos gordura saturada (enchidos, queijos gordos, manteiga, natas, fritos, bolos); mais fibra (leguminosas, legumes, fruta); peixe 2\u20133 vezes por semana; azeite; perder peso; caminhar.","Com pr\xe9-diabetes, tens\xe3o alta, obesidade e apneia, o seu alvo ser\xe1 provavelmente <70 ou <100 \u2014 confirme com o m\xe9dico. Subiu de 126 (2024) para 137 (2025) com rosuvastatina 5 mg (dose baixa).")
B.ewO=new A.hF("Gorduras",'O colesterol "bom": recolhe colesterol das art\xe9rias e leva-o ao f\xedgado. Quanto mais alto, melhor (homens: acima de 40).',null,"HDL baixo aumenta o risco cardiovascular. Baixa com excesso de peso, sedentarismo, tabaco, a\xe7\xfacar e triglic\xe9ridos altos.","Exerc\xedcio regular (\xe9 o que mais o sobe), perder peso, azeite e frutos secos, n\xe3o fumar.","Subiu de 43 para 51 \u2014 est\xe1 no bom caminho.")
B.ewg=new A.hF("Gorduras",'Colesterol total menos o HDL: todo o colesterol "mau" junto.',"Mesmo significado do LDL alto.",null,"Igual ao LDL.",null)
B.ex1=new A.hF("Gorduras","Gordura do sangue que vem sobretudo do a\xe7\xfacar, farinhas, \xe1lcool e excesso de calorias. Normal abaixo de 150.","Aumentam o risco cardiovascular e de f\xedgado gordo; muito altos (acima de 500) podem causar pancreatite. Andam de m\xe3os dadas com a resist\xeancia \xe0 insulina.",null,"Cortar a\xe7\xfacar, sumos, p\xe3o branco e \xe1lcool; perder peso; caminhar; peixe gordo (n\xe3o gosta de salm\xe3o \u2014 sardinha, cavala, carapau servem).","Desceram de 144 para 125.")
B.eww=new A.hF("F\xedgado","Enzima do f\xedgado (e dos m\xfasculos). Sobe quando as c\xe9lulas do f\xedgado se lesionam.","F\xedgado gordo, \xe1lcool, hepatites, alguns medicamentos; tamb\xe9m ap\xf3s exerc\xedcio intenso. Se persistir, o f\xedgado pode inflamar e criar cicatrizes (fibrose \u2192 cirrose) ao longo de anos.",null,"Perder peso, evitar \xe1lcool, cuidado com suplementos e paracetamol em excesso.",null)
B.ewZ=new A.hF("F\xedgado","A enzima mais espec\xedfica do f\xedgado. Sobe quando as c\xe9lulas do f\xedgado sofrem.","F\xedgado gordo (a causa mais comum com excesso de peso), \xe1lcool, hepatites, medicamentos (incluindo estatinas, raramente).",null,"Perder 7\u201310% do peso faz desaparecer muito do f\xedgado gordo; evitar \xe1lcool e refrigerantes.","Desceu de 45 (2024) para 27 (2025): melhorou.")
B.ews=new A.hF("F\xedgado","Enzima do f\xedgado e das vias biliares; \xe9 muito sens\xedvel ao \xe1lcool, ao f\xedgado gordo e a alguns medicamentos.",'Sinal de que o f\xedgado est\xe1 "sob stress": f\xedgado gordo, \xe1lcool (mesmo moderado), medicamentos, problemas da ves\xedcula ou das vias biliares. Mantida alta, associa-se a mais risco de diabetes e doen\xe7a cardiovascular.',null,"Zero \xe1lcool durante alguns meses e repetir; perder peso; ecografia abdominal se o m\xe9dico achar necess\xe1rio.","Est\xe1 alta desde 2016 (141 \u2192 137 \u2192 106). Melhorou em 2025 mas continua acima de 73 \u2014 vale a pena perguntar por uma ecografia ao f\xedgado.")
B.ewz=new A.hF("F\xedgado","Enzima do f\xedgado, vias biliares e ossos.","Problemas das vias biliares (pedras), do f\xedgado ou dos ossos; falta de vitamina D.",null,"Interpreta-se com a GGT e a bilirrubina.",null)
B.ewG=new A.hF("F\xedgado","Pigmento amarelo que resulta da destrui\xe7\xe3o normal dos gl\xf3bulos vermelhos e \xe9 eliminado pelo f\xedgado.","Olhos e pele amarelos (icter\xedcia): problemas do f\xedgado, ves\xedcula ou s\xedndrome de Gilbert (benigno, frequente).",null,"O m\xe9dico investiga a causa.",null)
B.ewb=new A.hF("F\xedgado","Principal prote\xedna do sangue, feita pelo f\xedgado. Mostra nutri\xe7\xe3o e fun\xe7\xe3o do f\xedgado.",null,"M\xe1 nutri\xe7\xe3o, doen\xe7a do f\xedgado ou perda pelos rins; provoca incha\xe7o das pernas.","Alimenta\xe7\xe3o com prote\xedna suficiente.",null)
B.ewa=new A.hF("Pr\xf3stata","Prote\xedna produzida pela pr\xf3stata. Normal abaixo de 4 ng/mL (sobe um pouco com a idade).","Pode subir com pr\xf3stata aumentada (benigna, muito comum ap\xf3s os 50), inflama\xe7\xe3o/infe\xe7\xe3o (prostatite), ejacula\xe7\xe3o ou bicicleta nos 2 dias anteriores, algalia\xe7\xe3o \u2014 e tamb\xe9m com cancro da pr\xf3stata. Por isso um valor alto n\xe3o \xe9 diagn\xf3stico: repete-se e, se se confirmar, vai-se \xe0 urologia (toque retal, resson\xe2ncia magn\xe9tica, eventualmente bi\xf3psia).",null,"Repetir sem ejacula\xe7\xe3o nem bicicleta nas 48 h anteriores; pedir PSA livre; manter vigil\xe2ncia anual.","Subiu de 1,25 (2016) para 4,43 (2024) e n\xe3o foi repetido em 2025. Mais do que o valor, preocupa a subida: pe\xe7a para repetir e, se continuar acima de 4, consulta de urologia.")
B.ewD=new A.hF("Sais","Sal do sangue; regula a \xe1gua do corpo.","Normalmente desidrata\xe7\xe3o.","Os diur\xe9ticos (hidroclorotiazida) podem baix\xe1-lo: cansa\xe7o, n\xe1useas, confus\xe3o, quedas.","Beber \xe1gua de forma regular; n\xe3o exagerar em litros de \xe1gua de uma vez.","Com hidroclorotiazida conv\xe9m vigiar o s\xf3dio e o pot\xe1ssio 1\u20132 vezes por ano. Os seus est\xe3o normais.")
B.ewN=new A.hF("Sais","Sal essencial para os m\xfasculos e o ritmo do cora\xe7\xe3o.","Pode causar arritmias graves. Sobe com olmesartan, problemas renais e alguns suplementos/substitutos de sal. Acima de 6 \xe9 urgente.","C\xe3ibras, fraqueza, palpita\xe7\xf5es. Baixa com a hidroclorotiazida.","N\xe3o usar substitutos de sal com pot\xe1ssio sem falar com o m\xe9dico; fruta e legumes normais s\xe3o seguros com rins normais.","Toma olmesartan (sobe o pot\xe1ssio) e hidroclorotiazida (baixa-o): vigiar 1\u20132 vezes por ano. 4,1 \xe9 perfeito.")
B.ewM=new A.hF("Sais","Sal que acompanha o s\xf3dio; ajuda o equil\xedbrio de \xe1gua e \xe1cidos.","Desidrata\xe7\xe3o ou altera\xe7\xf5es do equil\xedbrio \xe1cido.","V\xf3mitos, diur\xe9ticos.","Interpreta-se com o s\xf3dio.",null)
B.ewu=new A.hF("Urina","Gl\xf3bulos brancos na urina. Normal abaixo de 15/\xb5L.","Inflama\xe7\xe3o ou infe\xe7\xe3o das vias urin\xe1rias, pr\xf3stata (prostatite), pedras. Se a urocultura for negativa, n\xe3o \xe9 infe\xe7\xe3o bacteriana comum.",null,"Beber \xe1gua; repetir a an\xe1lise; tratar s\xf3 com indica\xe7\xe3o m\xe9dica.",null)
B.ex_=new A.hF("Urina","Gl\xf3bulos vermelhos (sangue) na urina vistos ao microsc\xf3pio. Normal abaixo de 15/\xb5L.","Pedras nos rins, pr\xf3stata aumentada, inflama\xe7\xe3o, exerc\xedcio intenso \u2014 mas em homens acima dos 50 tamb\xe9m \xe9 preciso excluir problemas da bexiga e do rim. A regra \xe9 repetir; se persistir, ecografia e urologia.",null,"Repetir a an\xe1lise sem exerc\xedcio intenso nas 48 h anteriores.","Em 12/07/2024 tinha 368/\xb5L (muito acima de 15). Se ainda n\xe3o foi repetida, pe\xe7a para repetir \u2014 sobretudo junto com o PSA que subiu.")
B.ewx=new A.hF("Inflama\xe7\xe3o","Marcador de inflama\xe7\xe3o no corpo.","Infe\xe7\xf5es, inflama\xe7\xe3o; ligeiramente alta e persistente associa-se a obesidade e risco cardiovascular.",null,"Perder peso e exerc\xedcio baixam a inflama\xe7\xe3o cr\xf3nica.",null)
B.ew6=new A.hF("Tiroide",'Hormona que "comanda" a tiroide.',"Tiroide pregui\xe7osa (hipotiroidismo): cansa\xe7o, frio, aumento de peso, obstipa\xe7\xe3o, colesterol alto.","Tiroide acelerada (hipertiroidismo): palpita\xe7\xf5es, perda de peso, tremores, nervosismo.","O m\xe9dico decide se \xe9 preciso tratar.",null)
B.ewc=new A.hF("Tiroide","Hormona produzida pela tiroide.","Tiroide acelerada.","Tiroide pregui\xe7osa.","Interpreta-se com a TSH.",null)
B.ewT=new A.hF("Sangue","Ferro a circular no sangue (varia muito ao longo do dia).","Suplementos ou acumula\xe7\xe3o de ferro.","Pode indicar falta de ferro (ver ferritina).","Interpreta-se com a ferritina.",null)
B.ewY=new A.hF("Sangue","Reserva de ferro do corpo.","Inflama\xe7\xe3o, f\xedgado gordo, \xe1lcool ou acumula\xe7\xe3o de ferro (hemocromatose).","Falta de ferro, mesmo antes da anemia: cansa\xe7o, queda de cabelo.","O m\xe9dico decide se \xe9 preciso ferro ou mais exames.",null)
B.ewq=new A.hF("Vitaminas","Vitamina dos ossos e m\xfasculos, feita na pele com o sol.",null,"Ossos fr\xe1geis, dores musculares, cansa\xe7o; muito comum em pessoas com excesso de peso.","Sol moderado; suplemento se o m\xe9dico indicar.",null)
B.ewQ=new A.hF("Vitaminas","Vitamina dos nervos e do sangue.",null,"Anemia, formigueiros, problemas de mem\xf3ria. Baixa com metformina e anti\xe1cidos de longa dura\xe7\xe3o.","Carne, peixe, ovos; suplemento se indicado.",null)
B.ewC=new A.hF("Tens\xe3o (MAPA)","M\xe9dia da tens\xe3o M\xc1XIMA ao longo de 24 h. Normal abaixo de 130 mmHg.",u.L,null,u.a,u.c9)
