B.iKx={HbA1c:0,"Glicemia m\xe9dia estimada":1,"Glicemia em jejum":2,"Albumina urin\xe1ria":3,"Rela\xe7\xe3o albumina/creatinina":4,Creatinina:5,"TFG (eGFR)":6,"Colesterol LDL":7,"Colesterol HDL":8,"Colesterol total":9,"Triglic\xe9ridos":10,"\xc1cido \xfarico":11,GGT:12,"TGP (ALT)":13,"TGO (AST)":14,Hemoglobina:15,PSA:16,"S\xf3dio":17,"Pot\xe1ssio":18,TSH:19,"Prote\xedna C reativa":20,"MAPA sist\xf3lica 24h":21,"Fra\xe7\xe3o de eje\xe7\xe3o":22,"Vitamina D":23,Ferritina:24}
B.fBq=s(["Este valor confirma diabetes ou \xe9 preciso repetir a an\xe1lise?","Qual deve ser o meu objetivo de HbA1c?","Chega mudar a alimenta\xe7\xe3o e caminhar, ou preciso de medica\xe7\xe3o?","Devo medir a glicemia em casa? Com que frequ\xeancia?","Preciso de exames aos olhos, aos rins e aos p\xe9s?","Quando repetimos a HbA1c (costuma ser de 3 em 3 meses at\xe9 estabilizar)?"],t.s)
B.evZ=new A.oR('Imagine que o a\xe7\xfacar deixa uma "cola" nos gl\xf3bulos vermelhos. Como eles duram cerca de 3 meses, medir essa cola d\xe1 a m\xe9dia do a\xe7\xfacar de todo esse per\xedodo, e n\xe3o s\xf3 do dia da colheita. Por isso n\xe3o se engana com um jantar mais pesado na v\xe9spera nem com um jejum mal feito.',B.fBq,"Sede intensa, urinar muito, perda de peso sem querer, vis\xe3o turva, feridas que n\xe3o saram ou uma glicemia medida acima de 300 mg/dL: n\xe3o espere pela pr\xf3xima consulta.")
B.fo8=s(["Que valor de glicemia em casa corresponde ao meu objetivo?","Os valores que me\xe7o em casa batem certo com esta m\xe9dia?"],t.s)
B.evI=new A.oR('Se a HbA1c \xe9 a "nota" em percentagem, a glicemia m\xe9dia estimada \xe9 a mesma nota na escala do dia a dia: diz "em m\xe9dia, nos \xfaltimos 2 a 3 meses, o seu a\xe7\xfacar andou \xe0 volta deste valor", na mesma unidade do medidor que se usa em casa. N\xe3o \xe9 uma an\xe1lise nova: \xe9 a HbA1c traduzida.',B.fo8,"Igual \xe0 HbA1c: sede intensa, urinar muito, vis\xe3o turva ou glicemia acima de 300 mg/dL pedem contacto com o m\xe9dico.")
B.hvO=s(["Preciso de repetir em jejum ou fazer uma prova de toler\xe2ncia \xe0 glicose?","Devo medir a glicemia em casa?"],t.s)
B.evS=new A.oR("\xc9 uma fotografia do a\xe7\xfacar naquele momento, depois de 8 a 12 horas sem comer. Muda com o stress, o sono e a refei\xe7\xe3o da v\xe9spera, por isso um valor isolado n\xe3o chega para dizer que h\xe1 diabetes: o m\xe9dico confirma repetindo ou com a HbA1c.",B.hvO,"Abaixo de 70 mg/dL com tremores, suores ou confus\xe3o, ou acima de 300 mg/dL com muita sede: procure ajuda no pr\xf3prio dia.")
B.Tl=s(["Os meus rins est\xe3o a funcionar bem para a minha idade?","Com que frequ\xeancia devo repetir estes exames?","Algum dos meus medicamentos pesa nos rins?"],t.s)
B.evM=new A.oR("O rim funciona como um coador de caf\xe9: deixa passar a \xe1gua e os res\xedduos e segura as prote\xednas. Se come\xe7a a aparecer albumina (uma prote\xedna) na urina, o coador est\xe1 a ficar menos apertado. \xc9 um dos primeiros sinais de cansa\xe7o do rim, muitas vezes antes de a creatinina mudar.",B.Tl,null)
B.evE=new A.oR('\xc9 a forma mais fi\xe1vel de ver se os rins deixam escapar prote\xedna: compara a albumina com a creatinina na mesma amostra, para que uma urina mais dilu\xedda ou mais concentrada n\xe3o engane. Abaixo de 30 mg/g \xe9 o esperado; entre 30 e 300 j\xe1 se diz "moderadamente aumentada"; acima de 300, "muito aumentada".',B.Tl,"Incha\xe7o novo nas pernas ou na cara, urina muito espumosa ou muito escura, ou urinar bastante menos do que o habitual.")
B.evW=new A.oR("A creatinina \xe9 um res\xedduo dos m\xfasculos que os rins eliminam. Se os rins filtram pior, ela acumula-se no sangue. Pessoas com mais m\xfasculo t\xeam valores um pouco mais altos sem que isso seja um problema.",B.Tl,null)
B.evP=new A.oR('Pense na TFG como "a percentagem de funcionamento do filtro do rim". 90 ou mais \xe9 \xf3timo; 60 a 89 \xe9 comum com a idade; abaixo de 60 durante mais de 3 meses fala-se de doen\xe7a renal cr\xf3nica. \xc9 calculada pela creatinina, a idade e o sexo, n\xe3o \xe9 medida diretamente.',B.Tl,null)
B.h2K=s(["Qual \xe9 o meu alvo de LDL, tendo em conta os meus outros riscos?","A dose da estatina \xe9 a adequada ou devemos mud\xe1-la?","Devo fazer an\xe1lises de controlo ao f\xedgado e m\xfasculos?"],t.s)
B.evL=new A.oR('O LDL \xe9 o colesterol que se pode ir depositando na parede das art\xe9rias (o "mau"). Com os anos forma placas que estreitam o cano e podem entupi-lo, causando enfarte ou AVC. Quanto mais fatores de risco (diabetes, tens\xe3o alta, tabaco, excesso de peso), mais baixo deve ser o alvo.',B.h2K,"Dor ou aperto no peito, falta de ar s\xfabita, fraqueza de um lado do corpo ou dificuldade a falar: ligue 112.")
B.h72=s(["O meu HDL est\xe1 bom para o meu risco?"],t.s)
B.evH=new A.oR('O HDL \xe9 o "cami\xe3o do lixo": apanha colesterol das art\xe9rias e leva-o de volta ao f\xedgado. Aqui, quanto mais alto, melhor. Sobe com exerc\xedcio e desce com sedentarismo, tabaco e excesso de peso.',B.h72,null)
B.hhq=s(["Que parte do total \xe9 o LDL e qual \xe9 o meu alvo?"],t.s)
B.ew_=new A.oR('\xc9 a soma de todo o colesterol, o bom e o mau. Sozinho diz pouco; o que o m\xe9dico olha \xe9 para o LDL e o HDL. Um total "normal" pode esconder um LDL alto.',B.hhq,null)
B.hjH=s(["Estava mesmo em jejum? Conv\xe9m repetir?","O \xe1lcool e os doces est\xe3o a contribuir?"],t.s)
B.evQ=new A.oR('S\xe3o a "gordura em tr\xe2nsito" no sangue. V\xeam sobretudo do que se come: a\xe7\xfacar, farinhas brancas, \xe1lcool e gorduras em excesso. Sobem muito depois de uma refei\xe7\xe3o, por isso a colheita deve ser em jejum.',B.hjH,"Valores acima de 500 mg/dL podem causar pancreatite (dor forte na barriga que irradia para as costas): procure o m\xe9dico de imediato.")
B.hqo=s(["Algum dos meus medicamentos faz subir o \xe1cido \xfarico?","Preciso de tratamento ou chega mudar a alimenta\xe7\xe3o?"],t.s)
B.evR=new A.oR("O \xe1cido \xfarico \xe9 o res\xedduo das purinas, que existem em carnes vermelhas, v\xedsceras, marisco e cerveja. Se h\xe1 demais, pode formar cristais, como sal no fundo de um copo, nas articula\xe7\xf5es (gota) e nos rins (pedras).",B.hqo,"Articula\xe7\xe3o (muitas vezes o dedo grande do p\xe9) muito dolorosa, quente e inchada de um dia para o outro, ou dor forte nas costas que vai para a virilha.")
B.fXI=s(["Devo fazer uma ecografia ao f\xedgado?","Os meus medicamentos podem estar a influenciar?"],t.s)
B.evD=new A.oR("A GGT \xe9 uma enzima do f\xedgado e das vias biliares. Funciona como um alarme: dispara com gordura no f\xedgado, \xe1lcool, alguns medicamentos e problemas da b\xedlis. Diz que h\xe1 irrita\xe7\xe3o, n\xe3o diz a causa.",B.fXI,"Pele ou olhos amarelados, urina escura com fezes claras, ou dor forte do lado direito da barriga.")
B.fPN=s(["Tenho f\xedgado gordo? Preciso de ecografia ou elastografia?"],t.s)
B.evG=new A.oR('A TGP (ALT) \xe9 uma enzima que vive dentro das c\xe9lulas do f\xedgado. Se as c\xe9lulas sofrem (gordura, \xe1lcool, v\xedrus, medicamentos), ela escapa para o sangue. \xc9 das melhores "campainhas" do f\xedgado.',B.fPN,null)
B.hiT=s(["Esta subida vem do f\xedgado ou do m\xfasculo?"],t.s)
B.evJ=new A.oR("A TGO (AST) \xe9 uma enzima do f\xedgado, mas tamb\xe9m do m\xfasculo e do cora\xe7\xe3o. Sobe com problemas do f\xedgado, mas tamb\xe9m depois de exerc\xedcio intenso ou de uma les\xe3o muscular.",B.hiT,null)
B.fVW=s(["Preciso de ver ferro, B12 ou \xe1cido f\xf3lico?"],t.s)
B.evX=new A.oR('A hemoglobina s\xe3o os "cami\xf5es" que levam o oxig\xe9nio dos pulm\xf5es para o corpo. Se h\xe1 poucos, cansa-se mais depressa, tem falta de ar e fica p\xe1lido; se h\xe1 demais, o sangue fica mais "grosso".',B.fVW,"Falta de ar em repouso, dor no peito, desmaio, ou fezes muito escuras ou com sangue.")
B.fH9=s(["Devo repetir o PSA e quando?","Conv\xe9m consulta de urologia ou outros exames?"],t.s)
B.evT=new A.oR("O PSA \xe9 uma prote\xedna feita pela pr\xf3stata. Sobe com o aumento benigno da pr\xf3stata, com inflama\xe7\xf5es e infe\xe7\xf5es, mas tamb\xe9m, por vezes, com cancro. Um valor alto n\xe3o \xe9 diagn\xf3stico: quer dizer que conv\xe9m olhar. O que mais pesa \xe9 a tend\xeancia ao longo dos anos.",B.fH9,"Sangue na urina, dificuldade grande em urinar, ou dor nova nas costas ou na bacia.")
B.fST=s(["Estes sais est\xe3o bem com a minha medica\xe7\xe3o?"],t.s)
B.evF=new A.oR("O s\xf3dio e o pot\xe1ssio s\xe3o os sais do sangue. O corpo mant\xe9m-nos num equil\xedbrio muito apertado, e os comprimidos da tens\xe3o (sobretudo os diur\xe9ticos) mexem neles, por isso se controlam.",B.fST,"Confus\xe3o, v\xf3mitos repetidos, c\xe3ibras fortes ou fraqueza intensa.")
B.fMt=s(["O pot\xe1ssio est\xe1 bem com os meus medicamentos?"],t.s)
B.evK=new A.oR("O pot\xe1ssio \xe9 essencial para o cora\xe7\xe3o e para os m\xfasculos. Pouco ou demais pode alterar o ritmo do cora\xe7\xe3o. Alguns medicamentos da tens\xe3o sobem-no, outros descem-no.",B.fMt,"Palpita\xe7\xf5es, desmaio ou fraqueza muscular intensa.")
B.fWn=s(["Preciso de ver tamb\xe9m T4 livre e anticorpos da tiroide?"],t.s)
B.evN=new A.oR('A TSH \xe9 o "chefe" que manda a tiroide trabalhar mais ou menos. TSH alta quer dizer que o chefe est\xe1 a gritar porque a tiroide est\xe1 pregui\xe7osa; TSH baixa, que a tiroide est\xe1 acelerada.',B.fWn,null)
B.fsN=s(["H\xe1 alguma infe\xe7\xe3o ou inflama\xe7\xe3o que explique este valor?"],t.s)
B.evY=new A.oR('\xc9 um alarme de inflama\xe7\xe3o no corpo. Sobe com infe\xe7\xf5es e inflama\xe7\xf5es, mas n\xe3o diz onde est\xe1 o problema, s\xf3 que h\xe1 "fogo" algures.',B.fsN,null)
B.hoV=s(["A minha tens\xe3o est\xe1 controlada ao longo das 24 horas?","Preciso de ajustar a medica\xe7\xe3o ou a hora a que a tomo?"],t.s)
B.evO=new A.oR("A MAPA \xe9 um aparelho que mede a tens\xe3o ao longo de 24 horas, enquanto faz a sua vida normal. \xc9 mais fi\xe1vel do que uma medi\xe7\xe3o no consult\xf3rio, onde o nervosismo pode subir a tens\xe3o. Mostra tamb\xe9m se a tens\xe3o desce \xe0 noite (o normal \xe9 descer 10 a 20%).",B.hoV,"Dor de cabe\xe7a muito forte, dor no peito, falta de ar, fraqueza de um lado do corpo ou dificuldade a falar: ligue 112.")
B.hfK=s(["O ecocardiograma deve ser repetido e quando?"],t.s)
B.evU=new A.oR("\xc9 a percentagem do sangue que o cora\xe7\xe3o empurra em cada batimento. 55 a 70% \xe9 o esperado. Pense numa pera de borracha: quanto da \xe1gua sai quando a aperta.",B.hfK,null)
B.heU=s(["Preciso de suplemento e em que dose?"],t.s)
B.evV=new A.oR("A vitamina D ajuda os ossos e os m\xfasculos. O corpo fabrica-a com o sol na pele, por isso falta mais no inverno e em quem passa o dia em espa\xe7os fechados.",B.heU,null)
B.fKh=s(["Preciso de ferro ou de investigar a causa?"],t.s)
B.ew0=new A.oR('A ferritina \xe9 o "armaz\xe9m de ferro" do corpo. Baixa quer dizer reservas vazias; alta pode ser inflama\xe7\xe3o ou excesso de ferro.',B.fKh,null)
